def find_shortest_path_length(n, ai, bi):
    if ai == 1 or bi == 1:
        return 1

    # Calculate the size of D(n-1) and D(n-2)
    size_n_minus_1 = (1 << (n - 1)) - 1
    size_n_minus_2 = (1 << (n - 2)) - 1

    if ai <= size_n_minus_1 and bi <= size_n_minus_1:
        return find_shortest_path_length(n - 1, ai, bi)
    elif ai > size_n_minus_1 and bi > size_n_minus_1:
        return find_shortest_path_length(n - 2, ai - size_n_minus_1, bi - size_n_minus_1)
    else:
        if ai <= size_n_minus_1:
            return min(find_shortest_path_length(n - 1, ai, size_n_minus_1) + 1, find_shortest_path_length(n - 1, ai, size_n_minus_1 + 1) + 2)
